import re, datetime, sys

def parse_ics(path):
    txt = open(path).read()
    events = []
    for m in re.finditer(r"BEGIN:VEVENT(.*?)END:VEVENT", txt, re.S):
        body = m.group(1)
        start = re.search(r"DTSTART(?:;[^:\n]*)?:(\S+)", body).group(1)
        end = re.search(r"DTEND(?:;[^:\n]*)?:(\S+)", body).group(1)
        s = datetime.datetime.strptime(start, "%Y%m%dT%H%M%SZ")
        e = datetime.datetime.strptime(end, "%Y%m%dT%H%M%SZ")
        events.append((s, e, body.strip()))
    return txt, events

def tomin(dt):
    return (dt - datetime.datetime(2000, 1, 1)).total_seconds() // 60

fail = []

# 1) Format checks on output file
txt, evs = parse_ics("/app/meeting_scheduled.ics")
if not txt.startswith("BEGIN:VCALENDAR"): fail.append("does not start with BEGIN:VCALENDAR")
if not txt.rstrip().endswith("END:VCALENDAR"): fail.append("does not end with END:VCALENDAR")
if "VERSION:2.0" not in txt: fail.append("missing VERSION:2.0")
if "PRODID" not in txt: fail.append("missing PRODID")
if len(evs) != 1: fail.append(f"expected 1 VEVENT, got {len(evs)}")
start, end, body = evs[0]
if re.search(r"SUMMARY:Team Planning Meeting", body) is None: fail.append("SUMMARY wrong")
for a in ["alice@example.com", "bob@example.com", "carol@example.com"]:
    if a not in body: fail.append(f"missing attendee {a}")
if (end - start) != datetime.timedelta(hours=1): fail.append("meeting is not exactly 1 hour")
for dt in (start, end):
    if not re.match(r"2024011[5-9]T\d{6}Z", dt.strftime("%Y%m%dT%H%M%SZ")):
        fail.append(f"date not in Jan 15-19 2024 UTC: {dt}")
    if dt.weekday() > 4: fail.append("weekend day")
    if dt.hour < 9 or dt > datetime.datetime(2024, 1, start.day, 18):
        fail.append(f"outside business hours: {dt}")
print(f"New meeting: {start} -> {end} ({start.strftime('%A')})")

# 2) Collect all existing events (union across all three calendars)
busy = []
for f in ["/app/alice_calendar.ics", "/app/bob_calendar.ics", "/app/carol_calendar.ics"]:
    _, e2 = parse_ics(f)
    busy += e2
    print(f"{f}: {len(e2)} events")

s, e = tomin(start), tomin(end)
for bs, be, _ in busy:
    bss, bee = tomin(bs), tomin(be)
    if bs.date() == start.date() and s < bee and e > bss:
        fail.append(f"conflicts with existing event {bs}-{be}")

# 3) Per-person hard constraints
if s < tomin(start.replace(hour=9, minute=0)): fail.append("Alice: before 9AM")
if e > tomin(start.replace(hour=14, minute=0)): fail.append("Alice: meeting after 2PM")
if s < tomin(start.replace(hour=10, minute=0)): fail.append("Bob: before 10AM")
if start.weekday() in (1, 3) and e > tomin(start.replace(hour=16, minute=30)):
    fail.append("Bob: after 4:30PM on Tue/Thu")
if s < tomin(start.replace(hour=9, minute=0)) or e > tomin(start.replace(hour=17, minute=0)):
    fail.append("Carol: outside 9-5")
lunch_s = tomin(start.replace(hour=12, minute=0))
lunch_e = tomin(start.replace(hour=12, minute=30))
if s < lunch_e and e > lunch_s: fail.append("Carol: overlaps lunch 12:00-12:30")
# Carol buffer: any existing Carol meeting ending at/after 16:45 -> need 15 min free after
for bs, be, _ in busy:
    if be.time() >= datetime.time(16, 45) and bs.date() == start.date():
        buf_end = tomin(be) + 15
        if s < buf_end and e > tomin(be):
            fail.append(f"Carol: missing 15-min buffer after meeting ending {be}")
if start.weekday() == 0:
    print("NOTE: slot is on Monday (Carol prefers to avoid Mondays)")

# 4) Verify earliest: scan every minute in business hours across the week
earliest = None
day = datetime.date(2024, 1, 15)
while day <= datetime.date(2024, 1, 19):
    for minute in range(9 * 60, 18 * 60 - 60 + 1):
        cand_s = day + datetime.timedelta(minutes=minute)
        cand_e = cand_s + datetime.timedelta(hours=1)
        cs, ce = tomin(cand_s), tomin(cand_e)
        ok = True
        # Alice
        if cs < 9 * 60 or ce > 14 * 60: ok = False
        # Bob
        if cs < 10 * 60: ok = False
        if cand_s.weekday() in (1, 3) and ce > 16 * 60 + 30: ok = False
        # Carol
        if cs < 9 * 60 or ce > 17 * 60: ok = False
        if cs < 12 * 60 + 30 and ce > 12 * 60: ok = False
        # conflicts with any existing event
        for bs, be, _ in busy:
            if bs.date() == day and cs < tomin(be) and ce > tomin(bs): ok = False
        # Carol 15-min buffer after meetings ending >= 16:45
        for bs, be, _ in busy:
            if be.time() >= datetime.time(16, 45) and bs.date() == day:
                if cs < tomin(be) + 15 and ce > tomin(be): ok = False
        if ok and earliest is None:
            earliest = cand_s
    day += datetime.timedelta(days=1)
print(f"Earliest hard-valid slot (minute scan): {earliest}")
if earliest != start:
    fail.append(f"chosen slot {start} is not earliest {earliest}")

print()
if fail:
    print("FAILURES:")
    for f_ in fail: print(" -", f_)
    sys.exit(1)
print("ALL CHECKS PASSED")

